/**
 * Public endpoint used by the claim landing page to render the invite
without requiring sign-in. A token that has already been claimed is
still resolvable (so the landing page can show a "this invite was
already accepted" state) and is signaled by `alreadyClaimed: true`
in the response body. Tokens that do not exist or have expired
return 404.

 * @summary Resolve an invite token to its preview metadata
 */
export const getGetInviteUrl = (token: string) => {
  return `/api/invites/${token}`;
};

export const getInvite = async (
  token: string,
  options?: RequestInit,
): Promise<InvitePreview> => {
  return customFetch<InvitePreview>(getGetInviteUrl(token), {
    ...options,
    method: "GET",
  });
};

export const getGetInviteQueryKey = (token: string) => {
  return [`/api/invites/${token}`] as const;
};

export const getGetInviteQueryOptions = <
  TData = Awaited<ReturnType<typeof getInvite>>,
  TError = ErrorType<ErrorResponse>,
>(
  token: string,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getInvite>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetInviteQueryKey(token);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getInvite>>> = ({
    signal,
  }) => getInvite(token, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!token,
    ...queryOptions,
  } as UseQueryOptions<Awaited<ReturnType<typeof getInvite>>, TError, TData> & {
    queryKey: QueryKey;
  };
};

export type GetInviteQueryResult = NonNullable<
  Awaited<ReturnType<typeof getInvite>>
>;
export type GetInviteQueryError = ErrorType<ErrorResponse>;

