/**
 * Converts a city/place name to latitude, longitude, and timezone
 * @summary Geocode a place name to coordinates
 */
export const getGeocodePlaceUrl = (params: GeocodePlaceParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/geocode?${stringifiedParams}`
    : `/api/geocode`;
};

export const geocodePlace = async (
  params: GeocodePlaceParams,
  options?: RequestInit,
): Promise<GeocodeSearchResponse> => {
  return customFetch<GeocodeSearchResponse>(getGeocodePlaceUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getGeocodePlaceQueryKey = (params?: GeocodePlaceParams) => {
  return [`/api/geocode`, ...(params ? [params] : [])] as const;
};

